:root{--primary:#1d4ed8;--primary-dark:#1e40af;--primary-soft:#eff6ff;--success:#15803d;--success-soft:#f0fdf4;--danger:#b91c1c;--danger-soft:#fef2f2;--text:#172033;--muted:#667085;--border:#e4e7ec;--surface:#fff;--background:#f5f7fb}
*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--background);color:var(--text)}button,input,a{font:inherit}.account-header{background:linear-gradient(135deg,#1d4ed8,#2563eb);color:#fff;padding:24px 32px;box-shadow:0 8px 24px rgba(29,78,216,.16)}.account-header-inner,.account-container{width:min(1120px,100%);margin:0 auto}.account-header-inner{display:flex;justify-content:space-between;align-items:center;gap:20px}.account-header h1{margin:0;font-size:25px}.account-header p{margin:6px 0 0;font-size:13px;opacity:.9}.account-container{padding:28px 24px 44px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:9px 14px;border:1px solid transparent;border-radius:8px;text-decoration:none;font-size:13px;font-weight:800;cursor:pointer;transition:.16s ease}.btn:hover{transform:translateY(-1px)}.btn-primary{background:var(--primary);color:#fff}.btn-primary:hover{background:var(--primary-dark)}.btn-secondary{background:#fff;color:#344054;border-color:#d0d5dd}.btn-secondary:hover{background:#f9fafb}.btn-danger{background:#b91c1c;color:#fff}.btn-danger:hover{background:#991b1b}.alert{padding:13px 15px;margin-bottom:16px;border-radius:9px;font-size:13px;line-height:1.5}.alert-success{background:var(--success-soft);color:#166534;border:1px solid #bbf7d0}.alert-error{background:var(--danger-soft);color:#991b1b;border:1px solid #fecaca}.account-summary{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:17px;padding:20px 21px;margin-bottom:17px;background:#fff;border:1px solid var(--border);border-radius:14px;box-shadow:0 3px 12px rgba(16,24,40,.04)}.account-avatar{width:58px;height:58px;border-radius:16px;display:flex;align-items:center;justify-content:center;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;font-size:21px;font-weight:900}.account-summary h2{margin:0 0 5px;font-size:19px}.account-summary p{margin:0;color:#667085;font-size:12px;line-height:1.5}.account-summary-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.account-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.account-card{background:#fff;border:1px solid var(--border);border-radius:14px;box-shadow:0 3px 12px rgba(16,24,40,.04);overflow:hidden}.account-card.full{grid-column:1/-1}.card-head{padding:19px 20px;border-bottom:1px solid #eef0f3}.card-head h3{margin:0 0 5px;font-size:16px}.card-head p{margin:0;color:#667085;font-size:12px;line-height:1.55}.card-body{padding:20px}.form-stack{display:grid;gap:15px}.field label{display:block;margin-bottom:7px;color:#344054;font-size:12px;font-weight:800}.field input{width:100%;height:42px;border:1px solid #d0d5dd;border-radius:8px;padding:0 11px;background:#fff;color:#172033;outline:none}.field input:focus{border-color:#84adff;box-shadow:0 0 0 3px rgba(37,99,235,.09)}.field-help{margin-top:6px;color:#98a2b3;font-size:11px;line-height:1.45}.field-error{margin-top:6px;color:#b91c1c;font-size:11px;font-weight:700}.card-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:18px;padding-top:16px;border-top:1px solid #eef0f3}.saved-note{color:#15803d;font-size:12px;font-weight:800}.security-note{margin-bottom:15px;padding:12px 13px;background:#f8fafc;border:1px solid #e4e7ec;border-radius:9px;color:#475467;font-size:12px;line-height:1.55}.danger-card{border-color:#fecaca}.danger-card .card-head{background:#fffafa}.danger-card .card-head h3{color:#991b1b}.danger-details summary{cursor:pointer;display:inline-flex;align-items:center;gap:7px;list-style:none;color:#b91c1c;font-size:12px;font-weight:800}.danger-details summary::-webkit-details-marker{display:none}.danger-panel{margin-top:14px;padding:15px;background:#fef2f2;border:1px solid #fecaca;border-radius:10px}.danger-panel p{margin:0 0 13px;color:#7f1d1d;font-size:12px;line-height:1.55}.account-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.meta-box{padding:12px;background:#f8fafc;border:1px solid #eef0f3;border-radius:9px}.meta-box span{display:block;color:#98a2b3;font-size:10px;text-transform:uppercase;letter-spacing:.35px;font-weight:800}.meta-box strong{display:block;margin-top:5px;color:#344054;font-size:12px;line-height:1.45}
@media(max-width:780px){.account-header{padding:20px}.account-header-inner{align-items:flex-start;flex-direction:column}.account-container{padding:22px 16px 36px}.account-grid{grid-template-columns:1fr}.account-card.full{grid-column:auto}.account-summary{grid-template-columns:auto 1fr}.account-summary-actions{grid-column:1/-1;justify-content:flex-start}}
@media(max-width:520px){.account-summary{grid-template-columns:1fr}.account-avatar{width:52px;height:52px}.account-summary-actions,.card-actions{flex-direction:column;align-items:stretch}.account-summary-actions .btn,.card-actions .btn{width:100%}.account-meta{grid-template-columns:1fr}.card-head,.card-body{padding:17px}}
